// ============================================================
// TEST: Document_Tool — validates $json.fileType output
// which is what the Switch node reads
// ============================================================

const mockBinaryData = {
  pdf_by_mime:  { fileName: 'report',      mimeType: 'application/pdf' },
  pdf_by_ext:   { fileName: 'report.pdf',  mimeType: 'application/octet-stream' },
  txt_by_mime:  { fileName: 'notes',       mimeType: 'text/plain' },
  txt_by_ext:   { fileName: 'notes.txt',   mimeType: 'application/octet-stream' },
  docx_by_mime: { fileName: 'letter',      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' },
  docx_by_ext:  { fileName: 'letter.docx', mimeType: 'application/octet-stream' },
  csv_by_mime:  { fileName: 'data',        mimeType: 'text/csv' },
  csv_by_ext:   { fileName: 'data.csv',    mimeType: 'application/octet-stream' },
  xls_by_mime:  { fileName: 'sheet',       mimeType: 'application/vnd.ms-excel' },
  xls_by_ext:   { fileName: 'sheet.xls',   mimeType: 'application/octet-stream' },
  xlsx_by_mime: { fileName: 'sheet',       mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' },
  xlsx_by_ext:  { fileName: 'sheet.xlsx',  mimeType: 'application/octet-stream' },
  unsupported:  { fileName: 'image.png',   mimeType: 'image/png' },
};

const expected = {
  pdf_by_mime:  'pdf',   pdf_by_ext:  'pdf',
  txt_by_mime:  'txt',   txt_by_ext:  'txt',
  docx_by_mime: 'docx',  docx_by_ext: 'docx',
  csv_by_mime:  'csv',   csv_by_ext:  'csv',
  xls_by_mime:  'xls',   xls_by_ext:  'xls',
  xlsx_by_mime: 'xlsx',  xlsx_by_ext: 'xlsx',
  unsupported:  'unsupported'
};

// Mirrors your detection logic — CSV moved before TXT to fix mime clash
function simulateDocumentTool(binaryData) {
  const results = [];
  for (const key of Object.keys(binaryData)) {
    const file = binaryData[key];
    const fileName = (file.fileName || 'unknown');
    const fileNameLower = fileName.toLowerCase();
    const mimeType = file.mimeType || '';
    let fileType = null;

    if      (mimeType.includes('pdf')              || fileNameLower.endsWith('.pdf'))  fileType = 'pdf';
    else if (mimeType.includes('csv')              || fileNameLower.endsWith('.csv'))  fileType = 'csv';  // before 'text' to avoid text/csv clash
    else if (mimeType.includes('text')             || fileNameLower.endsWith('.txt'))  fileType = 'txt';
    else if (mimeType.includes('wordprocessingml') || fileNameLower.endsWith('.docx')) fileType = 'docx';
    else if (mimeType.includes('vnd.ms-excel')     || fileNameLower.endsWith('.xls'))  fileType = 'xls';
    else if (mimeType.includes('spreadsheetml')    || fileNameLower.endsWith('.xlsx')) fileType = 'xlsx';
    else fileType = 'unsupported';

    results.push({ json: { fileName, mimeType, fileType } });
  }
  return results;
}

// --- Run & Assert ---
const outputs_raw = simulateDocumentTool(mockBinaryData); // ← was missing
const keys = Object.keys(mockBinaryData);
const outputs = [];

outputs_raw.forEach((output, i) => {
  const key = keys[i];
  const actual = output.json.fileType;
  const exp = expected[key];
  const pass = actual === exp;

  outputs.push({
    json: {
      fileName: output.json.fileName,
      mimeType: output.json.mimeType,
      fileType: actual,          // ← exactly what {{ $json.fileType }} reads on the Switch
      _test: { name: key, expected: exp, status: pass ? '✅ PASS' : '❌ FAIL' }
    }
  });
});

return outputs;

const items = $input.all();
const documentToolData = $('File Type').all();
const results = [];

const fileNameMap = {};
documentToolData.forEach((doc, index) => {
  fileNameMap[index] = doc.json.fileName || `Document_${index + 1}`;
});

items.forEach((item, fileIndex) => {
  let text = '';
  let fileName = fileNameMap[fileIndex] || 'Unknown Document';

  if (item.json.data && Array.isArray(item.json.data)) {
    text = item.json.data
      .map((page, pageIndex) => {
        const pageText = (page.text || '').trim();

        if (!pageText || pageText.length < 5) return null;

        return `[Page ${pageIndex + 1}]\n${pageText}`;
      })
      .filter(page => page !== null)
      .join('\n\n');
  }
  else if (item.json.text) {
    text = (item.json.text || '').trim();
    fileName = item.json.fileName || fileName;
  }
  else if (item.json._test) {
    text = `[Mock PDF content for test: ${item.json._test.name}]`;
    fileName = item.json.fileName || fileName;
  }

  if (!text || text.trim().length < 10) return;

  results.push({
    json: {
      fileName: fileName,
      fileContent: text
    }
  });
});

return results;

