const items = $input.all();
const fileTypeData = $('File Type').all();

const fileNameMap = {};
fileTypeData.forEach((doc, index) => {
  fileNameMap[index] = doc.json.fileName || `Document_${index + 1}`;
});

const fileGroups = {};

items.forEach((item, index) => {
  const fileName = fileNameMap[index] || `Document_${index + 1}`;

  if (!fileGroups[fileName]) {
    fileGroups[fileName] = [];
  }

  const text = item.json.data || item.json.text || '';
  if (text.trim()) {
    fileGroups[fileName].push(text);
  }
});

// Return one item per file
return Object.entries(fileGroups).map(([fileName, contents]) => ({
  json: {
    fileName: fileName,
    fileContent: contents.join('\n')
  }
}));

const items = $input.all();

const fileName = $('XLSX files loop').first().json.fileName || 'Unknown';

return [{
  json: {
    fileName: fileName,
    row_count: items.length,
    fileContent: items.map(item => {
      const row = {};
      Object.entries(item.json)
        .filter(([key]) => key !== 'myNewField')
        .forEach(([key, value]) => row[key] = value);
      return row;
    })
  }
}];

const mammoth = require('mammoth');

const items = $input.all();
const results = [];

for (const item of items) {
  const binary = item.binary || {};
  const binaryKey = Object.keys(binary)[0];


  if (!binaryKey && item.json?._test) {
    results.push({
      json: {
        fileName: item.json.fileName || 'Unknown.docx',
        fileContent: `[Mock DOCX content for test: ${item.json._test.name}]`
      }
    });
    continue;
  }

  if (!binaryKey) continue;

  const fileName = binary[binaryKey]?.fileName || 'Unknown.docx';
  const buffer = await this.helpers.getBinaryDataBuffer(
    items.indexOf(item), 
    binaryKey
  );

  try {
    const result = await mammoth.extractRawText({ buffer });

    results.push({
      json: {
        fileName: fileName,
        fileContent: result.value
      },
      binary: {
        data: binary[binaryKey]
      }
    });
  } catch (err) {
    results.push({
      json: {
        fileName: fileName,
        fileContent: '',
        error: err.message
      }
    });
  }
}

return results;

const fileTypeData = $('File Type').all();
const items = $input.all();

const fileList = items.map((item, index) => {
  const fileName = fileTypeData[index]?.json?.fileName || item.json.fileName || 'Unknown file';
  return `- ${fileName}`;
}).join('\n');

return [{
  json: {
    message: `##### Unsupported Files\n\n The following file(s) could not be processed:\n${fileList}\n\n ###### Supported formats: PDF, TXT, CSV, XLS, XLSX, DOCX.\n\n----`
  }
}];
